import React, { useState } from "react";
import axios from 'axios';
import {  useNavigate } from "react-router-dom";

 const initialUser = {email :"" , password :"" , username :""}
 const Registration = () => {
    const [user , setUser] = useState(initialUser);
    const navigate = useNavigate();
    
    const signUp =async( ) =>{
      try {
        const url="http://localhost:1337/api/auth/local/register";
        if (user.username && user.email && user.password) {
          const res = await axios.post(url, user)
          if (res) {
            setUser (initialUser);
            navigate('/login');
          }
         
          
        }
      } catch (error) {
        alert(`Registration failed: ${error.message}`);
      }


    }
    const handleUserChange =( {target}) =>{
        const {name , value}=target;
        setUser((currentUser) => ({
            ...currentUser, [name] : value,
            
                }));
            
    }
    return (
        <div>
            <div>
                <h2> Sign up :</h2>
                <form>
          <div className="mb-3">
            
            <input type="text" name="username"  value={user.username} onChange={handleUserChange} placeholder="Enter full name" />
          </div>
          <div className="mb-3">
           
            <input type="email" name="email" value={user.email} onChange={handleUserChange}  placeholder="Enter your email" />
          </div>

           <div className="mb-3">
          <input type="password" name="password" value={user.password} onChange={handleUserChange}  placeholder="Enter Password" />
         </div>
          <button type="submit" className="btn btn-primary" onClick={signUp}>Sign Up</button>
          
        </form>
            </div>
        </div>
    )
 }
 export default Registration;
